mapper.select:
select finprodId, /**产品代码**/ finprodAbbr, /**产品简称**/ profitTypeCode, /**产品类型Code - 基金类型**/ profitType, /**产品类型- 基金类型**/ ccyCode, /**币种Code**/ ccy, /**币种**/ settleDate, /**确认日- 交割日**/ netRedemptionShare,/** 净申赎份额 **/ netRedemptionAmt,/**净申赎金额**/ divIntAmt,/** 分红付息金额**/ reShare, /** 再投份额 **/ shareLastDay, /** 上一日份额：默认为0,后面计算 **/ shareRemainderDay,/** 当日剩余份额：默认为0,后面计算 **/ pFinprodId,/**母金融产品代码，null值表示为根节点**/ hasChildren, /** 净值日、净值日资产净值**/ cpriceDate, unitCprice /** 净值日、净值日资产净值**/ from ( select cp.FINPROD_ID as finprodId, /**产品代码**/ cp.FINPROD_ABBR as finprodAbbr, /**产品简称**/ cp.profit_type as profitTypeCode, /**产品类型Code - 基金类型**/ cp.profit_type as profitType, /**产品类型- 基金类型**/ d.CCY as ccyCode, /**币种Code**/ d.CCY as ccy, /**币种**/ DATE_FORMAT(d.settle_date, '%Y-%m-%d') as settleDate, /**确认日- 交割日**/ SUM(CASE WHEN instr('C1,T18', d.ps) > 0 THEN IFNULL(d.share_amt, 0) /**C1:产品认购,T18:认购确认**/ WHEN instr('C3', d.ps) > 0 THEN IFNULL(d.share_amt, 0) /**C3:份额强增**/ WHEN instr('C2,T04,T05', d.ps) > 0 THEN IFNULL(d.share_amt, 0) /**C2:产品申购,T04:申购,T05:申购确认**/ WHEN instr('C4,T06,T19,T24', d.ps) > 0 THEN IFNULL(d.share_amt, 0) * -1 /**C4:产品赎回,T06:赎回,T19:赎回确认,T24:赎回到账**/ WHEN instr('C6', d.ps) > 0 THEN IFNULL(d.share_amt, 0) * -1 /**C6:份额强减**/ WHEN instr('C5,T07', d.ps) > 0 THEN IFNULL(d.share_amt, 0) * -1 /**C5:产品到期,T07:到期**/ WHEN instr('', d.ps) > 0 THEN IFNULL(d.share_amt, 0) * -1 /**提前终止份额,待添加**/ ELSE 0 END) as netRedemptionShare, /** 净申赎份额：对应产品在对应日期的认购份额+强增份额+申购份额-赎回份额-强减份额-到期份额-提前终止份额 **/
SUM(CASE WHEN instr('C1,T18', d.ps) > 0 THEN IFNULL(d.TRADE_AMT - IFNULL(D.FEE_AMT_PAY,0), 0) /**C1:产品认购,T18:认购确认**/ WHEN instr('C3', d.ps) > 0 THEN IFNULL(d.TRADE_AMT - IFNULL(D.FEE_AMT_PAY,0), 0) /**C3:份额强增**/ WHEN instr('C2,T04,T05', d.ps) > 0 THEN IFNULL(d.TRADE_AMT - IFNULL(D.FEE_AMT_PAY,0), 0) /**C2:产品申购,T04:申购,T05:申购确认**/ WHEN instr('C4,T06,T19,T24', d.ps) > 0 THEN IFNULL(d.TRADE_AMT - IFNULL(D.FEE_AMT_PAY,0), 0) * -1 /**C4:产品赎回,T06:赎回,T19:赎回确认,T24:赎回到账**/ WHEN instr('C6', d.ps) > 0 THEN IFNULL(d.TRADE_AMT - IFNULL(D.FEE_AMT_PAY,0), 0) * -1 /**C6:份额强减**/ WHEN instr('C5,T07', d.ps) > 0 THEN IFNULL(d.TRADE_AMT - IFNULL(D.FEE_AMT_PAY,0), 0) * -1 /**C5:产品到期,T07:到期**/ WHEN instr('', d.ps) > 0 THEN IFNULL(d.TRADE_AMT - IFNULL(D.FEE_AMT_PAY,0), 0) * -1 /**提前终止本金,待添加**/ ELSE 0 END) as netRedemptionAmt, /** 净申赎金额：对应产品在对应日期的认购交易本金+强增本金+申购交易本金-赎回交易本金-强减本金-到期本金-提前终止本金**/
IFNULL(SUM(CASE WHEN (instr('01,03', cp.profit_type) > 0 and instr('T11,T12', d.ps) > 0) THEN IFNULL(d.INT_AMT, 0) /** 净值型 货币型产品在对应日期发生的分红（现金分红、红利再投）金额 **/ WHEN (instr('02', cp.profit_type) > 0 and instr('C7,T09,T22', d.ps) > 0) THEN IFNULL(d.INT_AMT, 0) /** 预期收益型产品在对应日期发生的付息金额 **/ ELSE 0 END ),0) as divIntAmt, /** 分红付息金额**/ SUM(CASE /**红利再投产品不会存在.只有红利转投类型会存在 leipeng 20180925**/ WHEN (instr('01,03', cp.profit_type) > 0 and instr('C10', d.ps) > 0) THEN IFNULL(d.share_amt, 0) /** 净值型 货币型产品在对应日期发生的红利再投份额 **/ ELSE 0 END) as reShare, /** 再投份额 **/ 0 as shareLastDay, /** 上一日份额：默认为0,后面计算 **/ 0 as shareRemainderDay, /** 当日剩余份额：默认为0,后面计算 **/ IFNULL(cp.p_finprod_id,'0') as pFinprodId, /**母金融产品代码，0值表示为根节点**/ (case when count(scp.p_finprod_id) > 0 then '01' else '02' end) as hasChildren, /** 净值日、净值日资产净值**/ MAX((case when (cp.profit_type='01') then DATE_FORMAT(d.CPRICE_DATE, '%Y-%m-%d') else null end ))as cpriceDate, MAX((case when (cp.profit_type='01') then d.UNIT_CPRICE else null end ))as unitCprice /** 净值日、净值日资产净值**/ from FIN_PRODUCT cp left join FIN_PRODUCT scp on scp.p_finprod_id = cp.finprod_id inner join TRD_PRODUCT_DEAL d on ( cp.finprod_id = d.finprod_id or scp.finprod_id = d.finprod_id ) where 1=1 and d.busi_type in('17','21','27') and d.SETTLE_DATE is not null and d.trade_status in ('01','02') and (d.f_trade_id not in (select t.f_trade_id from TRD_PRODUCT_DEAL t where t.trade_status = '03'
and t.busi_type in('17','21','27') and t.f_trade_id is not null
) or d.f_trade_id is null )
AND (cp.finprod_abbr like concat_ws('','%' ,#{search} , '%' ) OR cp.finprod_id like concat_ws('','%' ,#{search} , '%' ) )
AND cp.finprod_id in
#{item}
and d.SETTLE_DATE >= STR_TO_DATE(#{settleDateBegin},'%Y-%m-%d')
and d.SETTLE_DATE <= STR_TO_DATE(#{settleDateEnd},'%Y-%m-%d')
AND cp.ccy IN
#{item}
AND cp.profit_type in
#{item}
AND cp.issue_Type in
#{item}
AND cp.P_FINPROD_ID IS NULL
AND cp.P_FINPROD_ID IS NOT NULL
group by cp.FINPROD_ID, /**产品代码**/ cp.FINPROD_ABBR, /**产品简称**/ cp.profit_type, /**产品类型Code- 收益类型**/ cp.profit_type, /**产品类型- 收益类型**/ d.CCY, /**币种Code**/ d.CCY, /**币种**/ d.SETTLE_DATE, /**确认日- 交割日**/ cp.p_finprod_id/**母金融产品代码**/ /** 净值日、净值日资产净值**/
/** 净值日、净值日资产净值**/ order by d.SETTLE_DATE desc ) de

SELECT A.FINPROD_ID AS code, A.FINPROD_NAME AS name, A.FINPROD_ID AS hidCode, A.FINPROD_ABBR AS shortName FROM FIN_PRODUCT A WHERE A.FINPROD_TYPE = #{finprodType}
AND A.PROFIT_TYPE IN
#{item}
AND ( A.FINPROD_ID like concat_ws('','%' , #{param} , '%') OR A.FINPROD_NAME LIKE concat_ws('','%' , #{param} , '%'))
